-- 購入ログ
create table purchase_log (
  log_id varchar(100) not null
  , product_id varchar(100) not null
  , purchase_date timestamp not null
  , amount integer not null
  , delete_flag boolean not null
  , constraint purchase_log_PKC primary key (log_id)
) ;

-- 商品マスタ
create table product (
  product_id varchar(100) not null
  , product_name varchar(100) not null
  , price integer not null
  , create_date timestamp not null
  , misc varchar(100)
  , update_date timestamp
  , delete_flag boolean not null
  , constraint product_PKC primary key (product_id)
) ;

comment on table purchase_log is '購入ログ';
comment on column purchase_log.log_id is 'ログID';
comment on column purchase_log.product_id is '商品ID';
comment on column purchase_log.purchase_date is '購入日時';
comment on column purchase_log.amount is '数量';
comment on column purchase_log.delete_flag is '削除フラグ';

comment on table product is '商品マスタ';
comment on column product.product_id is '商品ID';
comment on column product.product_name is '商品名';
comment on column product.price is '価格';
comment on column product.create_date is '作成日';
comment on column product.misc is '備考';
comment on column product.update_date is '更新日';
comment on column product.delete_flag is '削除フラグ';

